// Calculate YoY and QoQ trends for financial metrics
const historicalData = items;
const webhookData = $('Webhook Trigger').item.json.body;

console.log(`Processing ${historicalData.length} historical metric rows`);

// Group metrics by period
const metricsByPeriod = {};

for (const item of historicalData) {
  const period = item.json.period;
  const metricName = item.json.metric_name;

  if (!metricsByPeriod[period]) {
    metricsByPeriod[period] = {};
  }

  metricsByPeriod[period][metricName] = {
    value: parseFloat(item.json.value),
    unit: item.json.unit,
    confidence: parseFloat(item.json.confidence),
    raw_name: item.json.raw_metric_name,
    category: item.json.category,
    document_name: item.json.document_name,
    date_added: item.json.date_added
  };
}

// Sort periods chronologically (assuming format like "2024-Q1", "2023-Q4", etc.)
const periods = Object.keys(metricsByPeriod).sort().reverse();
console.log('Periods found:', periods);

if (periods.length === 0) {
  return [{
    json: {
      error: 'No historical data found',
      company_name: webhookData.company_name,
      folder_id: webhookData.folder_id,
      periods_analyzed: 0
    }
  }];
}

// Helper function to calculate percentage change
function calculateChange(current, previous) {
  if (!previous || previous === 0) return null;
  return ((current - previous) / Math.abs(previous)) * 100;
}

// Helper function to determine trend direction
function getTrendDirection(changePercent) {
  if (changePercent === null) return 'unknown';
  if (Math.abs(changePercent) < 5) return 'stable';
  return changePercent > 0 ? 'growing' : 'declining';
}

// Helper function to determine significance
function getSignificance(changePercent) {
  if (changePercent === null) return 'unknown';
  const absChange = Math.abs(changePercent);
  if (absChange >= 20) return 'high';
  if (absChange >= 10) return 'moderate';
  return 'low';
}

// Calculate trends for the latest period
const latestPeriod = periods[0];
const latestMetrics = metricsByPeriod[latestPeriod];

const enrichedMetrics = [];

for (const [metricName, metricData] of Object.entries(latestMetrics)) {
  const enrichedMetric = {
    metric_name: metricName,
    raw_name: metricData.raw_name,
    category: metricData.category,
    current_period: latestPeriod,
    current_value: metricData.value,
    unit: metricData.unit,
    confidence: metricData.confidence
  };

  // Find QoQ (Quarter over Quarter) comparison
  if (periods.length >= 2) {
    const priorQuarter = periods[1];
    if (metricsByPeriod[priorQuarter] && metricsByPeriod[priorQuarter][metricName]) {
      const priorValue = metricsByPeriod[priorQuarter][metricName].value;
      const qoqChange = calculateChange(metricData.value, priorValue);

      enrichedMetric.qoq_prior_period = priorQuarter;
      enrichedMetric.qoq_prior_value = priorValue;
      enrichedMetric.qoq_change_percent = qoqChange;
      enrichedMetric.qoq_change_absolute = metricData.value - priorValue;
      enrichedMetric.qoq_trend = getTrendDirection(qoqChange);
      enrichedMetric.qoq_significance = getSignificance(qoqChange);
    }
  }

  // Find YoY (Year over Year) comparison
  // Assuming format like "2024-Q1" -> look for "2023-Q1"
  const yearMatch = latestPeriod.match(/(\d{4})/);
  if (yearMatch) {
    const currentYear = parseInt(yearMatch[1]);
    const priorYear = currentYear - 1;
    const yoyPeriod = latestPeriod.replace(currentYear.toString(), priorYear.toString());

    if (metricsByPeriod[yoyPeriod] && metricsByPeriod[yoyPeriod][metricName]) {
      const priorValue = metricsByPeriod[yoyPeriod][metricName].value;
      const yoyChange = calculateChange(metricData.value, priorValue);

      enrichedMetric.yoy_prior_period = yoyPeriod;
      enrichedMetric.yoy_prior_value = priorValue;
      enrichedMetric.yoy_change_percent = yoyChange;
      enrichedMetric.yoy_change_absolute = metricData.value - priorValue;
      enrichedMetric.yoy_trend = getTrendDirection(yoyChange);
      enrichedMetric.yoy_significance = getSignificance(yoyChange);
    }
  }

  enrichedMetrics.push(enrichedMetric);
}

// Prepare summary for analysis
const summary = {
  company_name: webhookData.company_name,
  folder_id: webhookData.folder_id,
  latest_period: latestPeriod,
  latest_document: webhookData.document_name,
  document_type: webhookData.document_type,
  periods_analyzed: periods.length,
  periods_available: periods,
  metrics_with_trends: enrichedMetrics,
  total_metrics: enrichedMetrics.length,
  has_qoq_data: periods.length >= 2,
  has_yoy_data: periods.length >= 5  // Rough estimate for YoY
};

console.log(`Calculated trends for ${enrichedMetrics.length} metrics`);
console.log(`Periods analyzed: ${periods.length}`);

return [{ json: summary }];

